app.source:
{
  "format": "complete-a-commitment/1",
  "module": {
    "id": "release-recovery",
    "version": "1.0.0",
    "template": {
      "id": "complete-a-commitment",
      "version": 1
    },
    "title": "Compare release arrangements",
    "question": "Which supplied release arrangements can satisfy the recorded scope, deadline, QA and spending requirements?",
    "description": "Compare four complete arrangements for an at-risk release. Reduced scope and a later date remain explicit amendments to the original commitment. This bounded calculation does not certify release quality or search all possible schedules.",
    "units": {
      "time": "minute",
      "timeOrigin": "minutes from the recorded release-planning origin",
      "money": "USD cent",
      "count": "resource"
    },
    "assumptions": [
      "Inputs describe fictional remaining QA work and recorded qualifications. Unknown workload or missing required facts leave the comparison unavailable; ticket status is not acceptance evidence.",
      "Core QA includes 240 minutes of independent regression and 60 minutes of integration sign-off. Primary core QA is the remaining recorded core work. Reporting QA is added to integration when included. All intervals are half-open working minutes.",
      "The existing QA resource represents one exclusive qualified allocation. Concurrent outside bookings reduce its availability through the shared capacity check. The additional QA resource can perform the authored independent regression package only.",
      "These four supplied schedules are not an exhaustive release scheduler. A different task dependency, a different transferable work package or a changed staffing structure requires an authored model revision.",
      "The original full scope and original deadline are retained in every outcome. A passing amended arrangement does not meet the original commitment unchanged.",
      "The additional fee is a flat accepted amount for the complete engagement, in currency cents; existing sunk costs and unmodeled quality risks are not estimated.",
      "Recorded prerequisite confirmation and authority do not authenticate an approver, perform tests, change the product scope, publish a release or prove successful operation."
    ],
    "inputs": {
      "parameters": {
        "coreMinutes": {
          "type": "integer",
          "unit": "time",
          "minimum": 301
        },
        "reportingMinutes": {
          "type": "integer",
          "unit": "time",
          "minimum": 1
        },
        "originalDeadline": {
          "type": "integer",
          "unit": "time",
          "minimum": 60
        },
        "proposedDeadline": {
          "type": "integer",
          "unit": "time",
          "minimum": 0
        },
        "acceptedRevisedDeadline": {
          "type": "integer",
          "unit": "time",
          "minimum": 0
        },
        "budgetMinor": {
          "type": "integer",
          "unit": "money",
          "minimum": 0
        },
        "extraFeeMinor": {
          "type": "integer",
          "unit": "money",
          "minimum": 0
        },
        "scopeRevisionAccepted": {
          "type": "boolean"
        },
        "dateRevisionAccepted": {
          "type": "boolean"
        },
        "prerequisiteConfirmed": {
          "type": "boolean"
        },
        "releaseAuthorized": {
          "type": "boolean"
        }
      },
      "tables": {
        "availability": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "resource": {
              "type": "string",
              "enum": [
                "existing-qa",
                "external-qa",
                "release-owner"
              ]
            },
            "from": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "through": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            }
          }
        },
        "qualifications": {
          "key": [
            "resource",
            "build",
            "environment",
            "from",
            "through"
          ],
          "columns": {
            "resource": {
              "type": "string",
              "enum": [
                "existing-qa",
                "external-qa"
              ]
            },
            "build": {
              "type": "string"
            },
            "environment": {
              "type": "string"
            },
            "from": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "through": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            }
          }
        },
        "bookings": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "resource": {
              "type": "string",
              "enum": [
                "existing-qa",
                "external-qa",
                "release-owner"
              ]
            },
            "from": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "through": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "amount": {
              "type": "integer",
              "unit": "count",
              "minimum": 0,
              "enum": [
                1
              ]
            }
          }
        },
        "scenarios": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string",
              "enum": [
                "recorded-release"
              ]
            }
          }
        },
        "_arrangements": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string",
              "enum": [
                "original",
                "core-only",
                "extra-help",
                "later-release"
              ]
            },
            "reportingIncluded": {
              "type": "boolean"
            },
            "reportingFactor": {
              "type": "integer",
              "unit": "count",
              "minimum": 0,
              "enum": [
                0,
                1
              ]
            },
            "requiresScopeRevision": {
              "type": "boolean"
            },
            "requiresDateRevision": {
              "type": "boolean"
            },
            "externalFactor": {
              "type": "integer",
              "unit": "count",
              "minimum": 0,
              "enum": [
                0,
                1
              ]
            },
            "serialFactor": {
              "type": "integer",
              "unit": "count",
              "minimum": 0,
              "enum": [
                0,
                1
              ]
            },
            "currentDayFactor": {
              "type": "integer",
              "unit": "count",
              "minimum": 0,
              "enum": [
                0,
                1
              ]
            },
            "laterFactor": {
              "type": "integer",
              "unit": "count",
              "minimum": 0,
              "enum": [
                0,
                1
              ]
            },
            "independentActor": {
              "type": "string",
              "enum": [
                "existing-qa",
                "external-qa"
              ]
            }
          }
        },
        "_resources": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string",
              "enum": [
                "existing-qa",
                "external-qa",
                "release-owner"
              ]
            },
            "capacity": {
              "type": "integer",
              "unit": "count",
              "minimum": 0,
              "enum": [
                1
              ]
            }
          }
        }
      }
    },
    "choices": [
      {
        "id": "arrangement",
        "domain": {
          "values": [
            "original",
            "core-only",
            "extra-help",
            "later-release"
          ]
        }
      }
    ],
    "scenarioDomain": {
      "table": "scenarios"
    },
    "lookupCoverage": [
      {
        "table": "_arrangements",
        "keys": {
          "id": {
            "domain": {
              "values": [
                "original",
                "core-only",
                "extra-help",
                "later-release"
              ]
            }
          }
        }
      },
      {
        "table": "_resources",
        "keys": {
          "id": {
            "domain": {
              "values": [
                "existing-qa",
                "external-qa",
                "release-owner"
              ]
            }
          }
        }
      }
    ],
    "derived": [
      {
        "id": "baselineCoreMinutes",
        "type": "integer",
        "unit": "time",
        "expr": {
          "ref": "parameter.coreMinutes"
        }
      },
      {
        "id": "baselineReportingMinutes",
        "type": "integer",
        "unit": "time",
        "expr": {
          "ref": "parameter.reportingMinutes"
        }
      },
      {
        "id": "originalDeadline",
        "type": "integer",
        "unit": "time",
        "expr": {
          "ref": "parameter.originalDeadline"
        }
      },
      {
        "id": "originalQaDeadline",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "sub",
          "args": [
            {
              "ref": "parameter.originalDeadline"
            },
            {
              "literal": 60
            }
          ]
        }
      },
      {
        "id": "originalReportingIncluded",
        "type": "boolean",
        "expr": {
          "literal": true
        }
      },
      {
        "id": "proposedReportingIncluded",
        "type": "boolean",
        "expr": {
          "op": "lookup",
          "table": "_arrangements",
          "where": {
            "id": {
              "ref": "choice.arrangement"
            }
          },
          "column": "reportingIncluded"
        }
      },
      {
        "id": "requiresScopeRevision",
        "type": "boolean",
        "expr": {
          "op": "lookup",
          "table": "_arrangements",
          "where": {
            "id": {
              "ref": "choice.arrangement"
            }
          },
          "column": "requiresScopeRevision"
        }
      },
      {
        "id": "requiresDateRevision",
        "type": "boolean",
        "expr": {
          "op": "lookup",
          "table": "_arrangements",
          "where": {
            "id": {
              "ref": "choice.arrangement"
            }
          },
          "column": "requiresDateRevision"
        }
      },
      {
        "id": "originalCommitmentPreserved",
        "type": "boolean",
        "expr": {
          "op": "and",
          "args": [
            {
              "op": "not",
              "args": [
                {
                  "op": "lookup",
                  "table": "_arrangements",
                  "where": {
                    "id": {
                      "ref": "choice.arrangement"
                    }
                  },
                  "column": "requiresScopeRevision"
                }
              ]
            },
            {
              "op": "not",
              "args": [
                {
                  "op": "lookup",
                  "table": "_arrangements",
                  "where": {
                    "id": {
                      "ref": "choice.arrangement"
                    }
                  },
                  "column": "requiresDateRevision"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "revisionAccepted",
        "type": "boolean",
        "expr": {
          "op": "and",
          "args": [
            {
              "op": "or",
              "args": [
                {
                  "op": "not",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "_arrangements",
                      "where": {
                        "id": {
                          "ref": "choice.arrangement"
                        }
                      },
                      "column": "requiresScopeRevision"
                    }
                  ]
                },
                {
                  "ref": "parameter.scopeRevisionAccepted"
                }
              ]
            },
            {
              "op": "or",
              "args": [
                {
                  "op": "not",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "_arrangements",
                      "where": {
                        "id": {
                          "ref": "choice.arrangement"
                        }
                      },
                      "column": "requiresDateRevision"
                    }
                  ]
                },
                {
                  "op": "and",
                  "args": [
                    {
                      "ref": "parameter.dateRevisionAccepted"
                    },
                    {
                      "op": "eq",
                      "args": [
                        {
                          "ref": "parameter.acceptedRevisedDeadline"
                        },
                        {
                          "ref": "parameter.proposedDeadline"
                        }
                      ]
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "applicableDeadline",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "add",
          "args": [
            {
              "op": "mul",
              "args": [
                {
                  "ref": "parameter.originalDeadline"
                },
                {
                  "op": "lookup",
                  "table": "_arrangements",
                  "where": {
                    "id": {
                      "ref": "choice.arrangement"
                    }
                  },
                  "column": "currentDayFactor"
                }
              ]
            },
            {
              "op": "mul",
              "args": [
                {
                  "ref": "parameter.proposedDeadline"
                },
                {
                  "op": "lookup",
                  "table": "_arrangements",
                  "where": {
                    "id": {
                      "ref": "choice.arrangement"
                    }
                  },
                  "column": "laterFactor"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "qaMinutes",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "add",
          "args": [
            {
              "ref": "parameter.coreMinutes"
            },
            {
              "op": "mul",
              "args": [
                {
                  "ref": "parameter.reportingMinutes"
                },
                {
                  "op": "lookup",
                  "table": "_arrangements",
                  "where": {
                    "id": {
                      "ref": "choice.arrangement"
                    }
                  },
                  "column": "reportingFactor"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "extraExpense",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "mul",
          "args": [
            {
              "ref": "parameter.extraFeeMinor"
            },
            {
              "op": "lookup",
              "table": "_arrangements",
              "where": {
                "id": {
                  "ref": "choice.arrangement"
                }
              },
              "column": "externalFactor"
            }
          ]
        }
      },
      {
        "id": "independentCoreDuration",
        "type": "integer",
        "unit": "time",
        "expr": {
          "literal": 240
        }
      },
      {
        "id": "nextDayIntegrationMinute",
        "type": "integer",
        "unit": "time",
        "expr": {
          "literal": 1440
        }
      },
      {
        "id": "primaryCoreDuration",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "sub",
          "args": [
            {
              "ref": "parameter.coreMinutes"
            },
            {
              "literal": 300
            }
          ]
        }
      },
      {
        "id": "integrationDuration",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "add",
          "args": [
            {
              "literal": 60
            },
            {
              "op": "mul",
              "args": [
                {
                  "ref": "parameter.reportingMinutes"
                },
                {
                  "op": "lookup",
                  "table": "_arrangements",
                  "where": {
                    "id": {
                      "ref": "choice.arrangement"
                    }
                  },
                  "column": "reportingFactor"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "integrationStart",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "add",
          "args": [
            {
              "op": "mul",
              "args": [
                {
                  "ref": "derived.primaryCoreDuration"
                },
                {
                  "op": "lookup",
                  "table": "_arrangements",
                  "where": {
                    "id": {
                      "ref": "choice.arrangement"
                    }
                  },
                  "column": "currentDayFactor"
                }
              ]
            },
            {
              "op": "mul",
              "args": [
                {
                  "ref": "derived.independentCoreDuration"
                },
                {
                  "op": "lookup",
                  "table": "_arrangements",
                  "where": {
                    "id": {
                      "ref": "choice.arrangement"
                    }
                  },
                  "column": "serialFactor"
                }
              ]
            },
            {
              "op": "mul",
              "args": [
                {
                  "ref": "derived.nextDayIntegrationMinute"
                },
                {
                  "op": "lookup",
                  "table": "_arrangements",
                  "where": {
                    "id": {
                      "ref": "choice.arrangement"
                    }
                  },
                  "column": "laterFactor"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "completionMinute",
        "type": "integer",
        "unit": "time",
        "expr": {
          "ref": "activity.release-handoff.end"
        }
      }
    ],
    "activities": [
      {
        "id": "primary-core-qa",
        "actor": {
          "literal": "existing-qa"
        },
        "start": {
          "literal": 0
        },
        "duration": {
          "ref": "derived.primaryCoreDuration"
        },
        "resources": [
          {
            "resource": {
              "literal": "existing-qa"
            },
            "amount": {
              "literal": 1
            }
          }
        ]
      },
      {
        "id": "independent-regression",
        "actor": {
          "op": "lookup",
          "table": "_arrangements",
          "where": {
            "id": {
              "ref": "choice.arrangement"
            }
          },
          "column": "independentActor"
        },
        "start": {
          "ref": "activity.primary-core-qa.end"
        },
        "duration": {
          "literal": 240
        },
        "resources": [
          {
            "resource": {
              "op": "lookup",
              "table": "_arrangements",
              "where": {
                "id": {
                  "ref": "choice.arrangement"
                }
              },
              "column": "independentActor"
            },
            "amount": {
              "literal": 1
            }
          }
        ]
      },
      {
        "id": "integration-qa",
        "actor": {
          "literal": "existing-qa"
        },
        "start": {
          "ref": "derived.integrationStart"
        },
        "duration": {
          "ref": "derived.integrationDuration"
        },
        "resources": [
          {
            "resource": {
              "literal": "existing-qa"
            },
            "amount": {
              "literal": 1
            }
          }
        ]
      },
      {
        "id": "release-handoff",
        "actor": {
          "literal": "release-owner"
        },
        "start": {
          "ref": "activity.integration-qa.end"
        },
        "duration": {
          "literal": 60
        },
        "resources": [
          {
            "resource": {
              "literal": "release-owner"
            },
            "amount": {
              "literal": 1
            }
          }
        ]
      }
    ],
    "resources": {
      "definitions": {
        "table": "_resources",
        "idColumn": "id",
        "capacityColumn": "capacity"
      },
      "bookings": {
        "table": "bookings",
        "resourceColumn": "resource",
        "startColumn": "from",
        "endColumn": "through",
        "amountColumn": "amount"
      }
    },
    "requirements": [
      {
        "id": "SCOPE",
        "label": "Recorded release scope",
        "meaning": "Core QA is retained. Deferring reporting requires an explicitly accepted scope amendment for this release.",
        "waivable": false
      },
      {
        "id": "TIME",
        "label": "Recorded release deadline",
        "meaning": "All QA and the complete handoff finish by the original deadline or a proposed deadline matching the explicitly accepted revised deadline.",
        "waivable": false
      },
      {
        "id": "QUALIFICATION",
        "label": "Qualified QA for this build",
        "meaning": "Each actual QA resource has a qualification covering this build, environment and full assigned interval.",
        "waivable": false
      },
      {
        "id": "AVAILABILITY",
        "label": "Whole-activity availability",
        "meaning": "Recorded working availability covers every complete assigned activity.",
        "waivable": false
      },
      {
        "id": "CAPACITY",
        "label": "Exclusive QA and handoff resources",
        "meaning": "Activities and existing bookings cannot use the same exclusive resource simultaneously.",
        "waivable": false
      },
      {
        "id": "PREREQUISITES",
        "label": "Confirmed release prerequisite",
        "meaning": "The recorded prerequisite is confirmed; a ticket status alone does not establish it.",
        "waivable": false
      },
      {
        "id": "ACCESS",
        "label": "Recorded release authority",
        "meaning": "The recorded release authorization is present. This does not obtain an external approval.",
        "waivable": false
      },
      {
        "id": "BUDGET",
        "label": "Additional spending limit",
        "meaning": "The flat accepted fee for the complete additional QA engagement fits the recorded limit.",
        "waivable": false
      },
      {
        "id": "BASIS",
        "label": "Authored arrangement meaning",
        "meaning": "Case inputs cannot rewrite which scope, deadline or resources an arrangement represents.",
        "waivable": false
      }
    ],
    "constraints": [
      {
        "id": "meaning-original-reportingIncluded",
        "requirement": "BASIS",
        "kind": "predicate",
        "predicate": {
          "op": "eq",
          "args": [
            {
              "op": "lookup",
              "table": "_arrangements",
              "where": {
                "id": {
                  "literal": "original"
                }
              },
              "column": "reportingIncluded"
            },
            {
              "literal": true
            }
          ]
        }
      },
      {
        "id": "meaning-original-reportingFactor",
        "requirement": "BASIS",
        "kind": "predicate",
        "predicate": {
          "op": "eq",
          "args": [
            {
              "op": "lookup",
              "table": "_arrangements",
              "where": {
                "id": {
                  "literal": "original"
                }
              },
              "column": "reportingFactor"
            },
            {
              "literal": 1
            }
          ]
        }
      },
      {
        "id": "meaning-original-requiresScopeRevision",
        "requirement": "BASIS",
        "kind": "predicate",
        "predicate": {
          "op": "eq",
          "args": [
            {
              "op": "lookup",
              "table": "_arrangements",
              "where": {
                "id": {
                  "literal": "original"
                }
              },
              "column": "requiresScopeRevision"
            },
            {
              "literal": false
            }
          ]
        }
      },
      {
        "id": "meaning-original-requiresDateRevision",
        "requirement": "BASIS",
        "kind": "predicate",
        "predicate": {
          "op": "eq",
          "args": [
            {
              "op": "lookup",
              "table": "_arrangements",
              "where": {
                "id": {
                  "literal": "original"
                }
              },
              "column": "requiresDateRevision"
            },
            {
              "literal": false
            }
          ]
        }
      },
      {
        "id": "meaning-original-externalFactor",
        "requirement": "BASIS",
        "kind": "predicate",
        "predicate": {
          "op": "eq",
          "args": [
            {
              "op": "lookup",
              "table": "_arrangements",
              "where": {
                "id": {
                  "literal": "original"
                }
              },
              "column": "externalFactor"
            },
            {
              "literal": 0
            }
          ]
        }
      },
      {
        "id": "meaning-original-serialFactor",
        "requirement": "BASIS",
        "kind": "predicate",
        "predicate": {
          "op": "eq",
          "args": [
            {
              "op": "lookup",
              "table": "_arrangements",
              "where": {
                "id": {
                  "literal": "original"
                }
              },
              "column": "serialFactor"
            },
            {
              "literal": 1
            }
          ]
        }
      },
      {
        "id": "meaning-original-currentDayFactor",
        "requirement": "BASIS",
        "kind": "predicate",
        "predicate": {
          "op": "eq",
          "args": [
            {
              "op": "lookup",
              "table": "_arrangements",
              "where": {
                "id": {
                  "literal": "original"
                }
              },
              "column": "currentDayFactor"
            },
            {
              "literal": 1
            }
          ]
        }
      },
      {
        "id": "meaning-original-laterFactor",
        "requirement": "BASIS",
        "kind": "predicate",
        "predicate": {
          "op": "eq",
